import { useCallback, useEffect, useMemo, useState } from 'react'
import {
    DEFAULT_CARD_BODY_TEMPLATE,
    DEFAULT_CARD_TYPES,
    DEFAULT_STATES,
    type BranchReference,
    type CardDraft,
    type ProjectReference,
    type PushMode,
    type ReleaseBranchCandidate,
    type RepositoryReference,
    type TopLevelFolderReference,
} from '../../../data/data_types'
import { getElectronDataBridge } from '../../../data/electron_data_bridge'
import { readRecentLocalRepositories, recordRecentLocalRepository } from '../../../data/recent_local_repositories'
import type { StorageType } from '../../../data/project_session'
import { dialogService } from '../../../services/dialog_service'
import { configService } from '../../../services/config/config_service'
import { projectSessionService, type ProjectOpenResolution } from '../../../services/project/project_session_service'
import { useProjectConfig } from '../../hooks/use_project_config'
import { useConfigValueOrFallback } from '../../hooks/use_config_value'
import { useProjectSession } from '../../hooks/use_project_session'
import { useProjectState } from '../../hooks/use_project_state'
import {
    OPEN_NEW_CARD_DIALOG_EVENT,
    OPEN_PROJECT_DIALOG_EVENT,
    type OpenNewCardDialogDetail,
    type OpenProjectDialogDetail,
    type ProjectDialogSource,
} from '../../project_command_events'

type ProjectDialogMode = 'open' | 'branch' | 'card' | 'release'
type ProjectOpenResult = 'failed' | 'opened' | 'resolution'

const EMPTY_BRANCHES: BranchReference[] = []
const EMPTY_REPOSITORIES: RepositoryReference[] = []

interface UseProjectToolbarMenuActionsArgs {
    accessToken: string | null
    isGithubAuthenticated: boolean
    onCloseDialog: () => void
    onOpenDialog: (mode: ProjectDialogMode) => void
}

function branchExists(branches: BranchReference[], branchName: string) {
    return branches.some(({ name }) => name === branchName)
}

function branchValue(branches: BranchReference[], preferredBranch: string) {
    if (branchExists(branches, preferredBranch)) return preferredBranch

    return branches[0]?.name ?? ''
}

/** Owns project menu service calls and non-dialog session state. */
export function useProjectToolbarMenuActions(args: UseProjectToolbarMenuActionsArgs) {
    const { accessToken, isGithubAuthenticated, onCloseDialog, onOpenDialog } = args
    const { project, snapshot } = useProjectState()
    const projectSession = useProjectSession()
    const projectConfig = useProjectConfig()
    const electronBridge = useMemo(() => getElectronDataBridge(), [])
    const [branches, setBranches] = useState<BranchReference[]>(EMPTY_BRANCHES)
    const [isReleaseCompleting, setIsReleaseCompleting] = useState(false)
    const [projectOpenResolution, setProjectOpenResolution] = useState<ProjectOpenResolution | null>(null)
    const [initialProjectSource, setInitialProjectSource] = useState<ProjectDialogSource | null>(null)
    const [initialRemoteProject, setInitialRemoteProject] = useState<ProjectReference | null>(null)
    const [newCardInitialStatus, setNewCardInitialStatus] = useState('')
    const [pendingLocalRootPath, setPendingLocalRootPath] = useState<string | null>(null)
    const [recentLocalRepositories, setRecentLocalRepositories] = useState(() => readRecentLocalRepositories())
    const [repositories, setRepositories] = useState<RepositoryReference[]>(EMPTY_REPOSITORIES)
    const [releaseBranchCandidates, setReleaseBranchCandidates] = useState<ReleaseBranchCandidate[]>([])
    const [switchBranch, setSwitchBranch] = useState(project?.branch ?? '')
    const activeCards = snapshot?.activeCards ?? []
    const cardTypes = projectConfig?.cardTypes ?? DEFAULT_CARD_TYPES
    const cardBodyTemplate = projectConfig?.cardBodyTemplate ?? DEFAULT_CARD_BODY_TEMPLATE
    const states = projectConfig?.states ?? DEFAULT_STATES
    const pushMode = (projectConfig?.pushMode ?? 'auto') as PushMode
    const releaseSelectAllDefault = useConfigValueOrFallback('react.deleteBranchesAfterRelease', false)

    const closeDialog = useCallback(() => {
        onCloseDialog()
        setProjectOpenResolution(null)
        projectSessionService.setError(null)
    }, [onCloseDialog])

    const openProject = useCallback(async (storageType: StorageType, nextProject: ProjectReference): Promise<ProjectOpenResult> => {
        setProjectOpenResolution(null)

        try {
            const resolution = await projectSessionService.openProject(storageType, nextProject, accessToken)
            if (resolution) {
                setProjectOpenResolution(resolution)
                onOpenDialog('open')

                return 'resolution'
            }

            closeDialog()
            return 'opened'
        } catch {
            // ProjectSessionService emits the user-visible error.
            return 'failed'
        }
    }, [accessToken, closeDialog, onOpenDialog])

    const recordOpenedLocalProject = useCallback((rootPath: string) => {
        setRecentLocalRepositories(recordRecentLocalRepository(rootPath))
        setPendingLocalRootPath(null)
    }, [])

    const openResolvedLocalProject = useCallback(async (nextProject: ProjectReference) => {
        if (!nextProject.rootPath) throw new Error('Resolved local repository has no root path')

        const result = await openProject('local', nextProject)
        if (result === 'opened') recordOpenedLocalProject(nextProject.rootPath)
        if (result === 'resolution') setPendingLocalRootPath(nextProject.rootPath)
    }, [openProject, recordOpenedLocalProject])

    const chooseLocalProjectFolder = useCallback(async () => {
        if (!electronBridge) return

        let nextProject: ProjectReference | null
        try {
            nextProject = await electronBridge.openProjectFolder()
        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Local project selection failed' })

            return
        }

        if (nextProject) await openResolvedLocalProject(nextProject)
    }, [electronBridge, openResolvedLocalProject])

    const openLocalProject = useCallback(async (rootPath: string) => {
        if (!electronBridge) return

        const normalizedPath = rootPath.trim()
        if (normalizedPath.length === 0) return

        try {
            const nextProject = await electronBridge.resolveProject({ branch: '', id: normalizedPath, rootPath: normalizedPath })
            await openResolvedLocalProject(nextProject)
        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Local project selection failed' })
        }
    }, [electronBridge, openResolvedLocalProject])

    const loadRepositories = useCallback(async () => {
        try {
            setRepositories(await projectSessionService.listRepositories(accessToken))
        } catch {
            setRepositories(EMPTY_REPOSITORIES)
        }
    }, [accessToken])

    const loadSwitchBranches = useCallback(async () => {
        if (!project) return

        try {
            const storageType = project.rootPath ? 'local' : 'github'
            const nextBranches = await projectSessionService.listBranches(storageType, project, accessToken)
            setBranches(nextBranches)
            setSwitchBranch(branchValue(nextBranches, project.branch))
        } catch {
            // ProjectSessionService emits the user-visible error.
        }
    }, [accessToken, project])

    useEffect(() => {
        const handleOpenProjectDialog = (event: Event) => {
            const detail = (event as CustomEvent<OpenProjectDialogDetail>).detail
            setInitialProjectSource(detail?.source ?? null)
            setInitialRemoteProject(detail?.project ?? null)
            setProjectOpenResolution(detail?.resolution ?? null)
            onOpenDialog('open')
            if (isGithubAuthenticated) void loadRepositories()
        }

        window.addEventListener(OPEN_PROJECT_DIALOG_EVENT, handleOpenProjectDialog)

        return () => window.removeEventListener(OPEN_PROJECT_DIALOG_EVENT, handleOpenProjectDialog)
    }, [isGithubAuthenticated, loadRepositories, onOpenDialog])

    useEffect(() => {
        const handleOpenNewCardDialog = (event: Event) => {
            if (!project) return

            const { status } = (event as CustomEvent<OpenNewCardDialogDetail>).detail
            const initialStatus = states.some((stateConfig) => stateConfig.state === status) ? status : states[0]?.state
            setNewCardInitialStatus(initialStatus ?? '')
            onOpenDialog('card')
        }

        window.addEventListener(OPEN_NEW_CARD_DIALOG_EVENT, handleOpenNewCardDialog)

        return () => window.removeEventListener(OPEN_NEW_CARD_DIALOG_EVENT, handleOpenNewCardDialog)
    }, [onOpenDialog, project, states])

    const openNewCardDialog = () => {
        setNewCardInitialStatus(states[0]?.state ?? '')
        onOpenDialog('card')
    }

    const openProjectDialog = () => {
        setInitialProjectSource(null)
        setInitialRemoteProject(null)
        onOpenDialog('open')
        if (isGithubAuthenticated) void loadRepositories()
    }

    const openBranchDialog = () => {
        onOpenDialog('branch')
        void loadSwitchBranches()
    }

    const clearOpenDialogState = () => {
        setBranches(EMPTY_BRANCHES)
        setProjectOpenResolution(null)
    }

    const loadRepositoryBranches = async (repository: RepositoryReference) => {
        try {
            const nextBranches = await projectSessionService.listBranches('github', repository, accessToken)
            setBranches(nextBranches)

            return nextBranches
        } catch {
            setBranches(EMPTY_BRANCHES)

            return EMPTY_BRANCHES
        }
    }

    const loadManualBranches = async (owner: string, repositoryName: string, isPublic: boolean) => {
        try {
            const storageType = isPublic ? 'github-readonly' : 'github'
            const result = await projectSessionService.findGithubRepositoryBranches(owner, repositoryName, accessToken, storageType)
            setBranches(result.branches)

            return result
        } catch {
            return null
        }
    }

    const createRemoteProject = (rootPath: string, branch: string): ProjectReference | null => {
        try {
            if (rootPath.length === 0) throw new Error('Missing remote project root path')

            return { branch: branch || 'main', id: rootPath, rootPath }
        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Remote project could not be created' })

            return null
        }
    }

    const loadRemoteBranches = async (endpoint: string, rootPath: string, branch: string) => {
        const remoteProject = createRemoteProject(rootPath, branch)
        if (!remoteProject) {
            setBranches(EMPTY_BRANCHES)

            return EMPTY_BRANCHES
        }

        projectSessionService.configureRemote(endpoint)

        try {
            const nextBranches = await projectSessionService.listBranches('remote', remoteProject, accessToken)
            setBranches(nextBranches)

            return nextBranches
        } catch {
            setBranches(EMPTY_BRANCHES)

            return EMPTY_BRANCHES
        }
    }

    const openGithubProject = async (owner: string, repositoryName: string, branch: string, isPublic: boolean) => {
        try {
            const storageType = isPublic ? 'github-readonly' : 'github'
            const result = await projectSessionService.findGithubRepositoryBranches(owner, repositoryName, accessToken, storageType)
            const fallbackBranches = branches.length > 0 ? branches : result.branches
            const selectedBranch = branch || branchValue(fallbackBranches, result.repository.branch)
            setBranches(fallbackBranches)
            await openProject(storageType, { ...result.repository, branch: selectedBranch })
        } catch {
            // ProjectSessionService emits the user-visible error.
        }
    }

    const openRemoteProject = async (endpoint: string, nextProject: ProjectReference) => {
        projectSessionService.configureRemote(endpoint)
        await openProject('remote', nextProject)
    }

    const openWorkingFolder = async (folder: TopLevelFolderReference) => {
        if (projectOpenResolution?.kind !== 'missing-working-folder') return

        try {
            await projectSessionService.openWorkingFolder(projectOpenResolution, folder, accessToken)
            if (pendingLocalRootPath) recordOpenedLocalProject(pendingLocalRootPath)
            closeDialog()
        } catch {
            // ProjectSessionService emits the user-visible error.
        }
    }

    const createWorkingFolder = async () => {
        if (projectOpenResolution?.kind !== 'missing-working-folder') return

        try {
            await projectSessionService.createWorkingFolder(projectOpenResolution, accessToken)
            if (pendingLocalRootPath) recordOpenedLocalProject(pendingLocalRootPath)
            closeDialog()
        } catch {
            // ProjectSessionService emits the user-visible error.
        }
    }

    const createProjectFolders = async (projectFolder: string) => {
        if (projectOpenResolution?.kind !== 'project-folder-setup') return

        try {
            await projectSessionService.createProjectFolders(projectOpenResolution, projectFolder, accessToken)
            if (pendingLocalRootPath) recordOpenedLocalProject(pendingLocalRootPath)
            closeDialog()
        } catch {
            // ProjectSessionService emits the user-visible error.
        }
    }

    const switchProjectBranch = async (branch: string) => {
        try {
            await projectSessionService.switchBranch(branch)
            closeDialog()
        } catch {
            // ProjectSessionService emits the user-visible error.
        }
    }

    const openReleaseDialog = async () => {
        try {
            setReleaseBranchCandidates(await projectSessionService.getReleaseBranchCandidates())
            onOpenDialog('release')
        } catch {
            // ProjectSessionService emits the user-visible error.
        }
    }

    const completeRelease = async (releaseName: string, selectedBranchNames: string[]) => {
        setIsReleaseCompleting(true)
        try {
            await projectSessionService.completeRelease(releaseName, selectedBranchNames)
            closeDialog()
        } catch {
            // ProjectSessionService emits the user-visible error.
        } finally {
            setIsReleaseCompleting(false)
        }
    }

    const setReleaseSelectAllDefault = (selected: boolean) => {
        configService.setReactPreference('react.deleteBranchesAfterRelease', selected)
    }

    const createCard = async (draft: CardDraft, initialState: string) => {
        await projectSessionService.createCard(draft, initialState)
        closeDialog()
    }

    return {
        activeCards,
        branches,
        cardBodyTemplate,
        cardTypes,
        chooseLocalProjectFolder,
        clearOpenDialogState,
        closeDialog,
        commit: () => projectSessionService.commit(),
        completeRelease,
        initialProjectSource,
        initialRemoteProject,
        newCardInitialStatus,
        createCard,
        createProjectFolders,
        createRemoteProject,
        createWorkingFolder,
        isLoading: projectSession.isLoading,
        isDesktopMode: !!electronBridge,
        isProjectOpen: !!project,
        isReleaseCompleting,
        loadSwitchBranches,
        loadManualBranches,
        loadRemoteBranches,
        loadRepositoryBranches,
        projectOpenResolution,
        openBranchDialog,
        openGithubProject,
        openLocalProject,
        openNewCardDialog,
        openWorkingFolder,
        openProjectDialog,
        openRemoteProject,
        openReleaseDialog,
        pendingGithubConflictProject: projectSession.pendingGithubConflictProject,
        pull: () => projectSessionService.pull(),
        push: () => projectSessionService.push(),
        pushMode,
        recentLocalRepositories,
        repositories,
        releaseBranchCandidates,
        releaseSelectAllDefault,
        setReleaseSelectAllDefault,
        setSwitchBranch,
        states,
        switchBranch,
        switchProjectBranch,
    }
}

import { useSyncExternalStore } from 'react'
import type { ProjectConfig } from '../../data/data_types'
import { dataService, type DataService } from '../../services/data/data_service'

const snapshots = new WeakMap<DataService, ProjectConfig | null>()

function isSameProjectConfig(first: ProjectConfig | null, second: ProjectConfig | null) {
    return first?.actionsFolder === second?.actionsFolder
        && first?.archivedFolder === second?.archivedFolder
        && first?.backgroundShade === second?.backgroundShade
        && first?.cardBodyTemplate === second?.cardBodyTemplate
        && first?.cardTypes === second?.cardTypes
        && first?.diffCommand === second?.diffCommand
        && first?.projectFolder === second?.projectFolder
        && first?.pushMode === second?.pushMode
        && first?.releasesFolder === second?.releasesFolder
        && first?.states === second?.states
        && first?.workingFolder === second?.workingFolder
}

function getProjectConfigSnapshot(service: DataService): ProjectConfig | null {
    const nextSnapshot = service.getConfig()
    const currentSnapshot = snapshots.get(service)
    if (snapshots.has(service) && isSameProjectConfig(currentSnapshot ?? null, nextSnapshot)) return currentSnapshot ?? null

    snapshots.set(service, nextSnapshot)

    return nextSnapshot
}

/** Subscribe to project config exposed through the data service. */
export function useProjectConfig(service: DataService = dataService): ProjectConfig | null {
    return useSyncExternalStore(
        (onStoreChange) => {
            service.addEventListener('changed', onStoreChange)

            return () => service.removeEventListener('changed', onStoreChange)
        },
        () => getProjectConfigSnapshot(service),
        () => getProjectConfigSnapshot(service),
    )
}

import {
    defaultColumnAccent,
    type CardTypeConfig,
    type ProjectConfig,
    type StateConfig,
} from '../../data/data_types'
import { LEGACY_CARD_SEPARATOR } from '../../data/card_identifiers'
import { validateAgentProfiles, validatePermissionMode, validateThinkingLevel, type AgentProfile } from '../../data/agent_profiles'
import {
    CONFIG_ENTRIES,
    createDefaultValues,
    DESKTOP_KEYS,
    PROJECT_KEYS,
    requireConfigEntry,
    type ConfigEntry,
    type ConfigKey,
    type ConfigSource,
    type ConfigValue,
    type ConfigValueTypes,
    type ConfigValues,
    type DesktopConfigValues,
} from './config_entries'
import {
    mergeStoredReactValues,
    writeStoredReactValues,
} from './config_persistence'
import { register } from '../service_injector'

export {
    CONFIG_ENTRIES,
    CONFIG_SECTIONS,
    type ConfigEntry,
    type ConfigKey,
    type ConfigOption,
    type ConfigSource,
    type ConfigValue,
    type ConfigValueTypes,
    type ConfigValues,
    type ConfigValueType,
    type DesktopConfigValues,
} from './config_entries'
export { REACT_CONFIG_STORAGE_KEY, readStartupSplashPreference } from './config_persistence'

interface ConfigServiceInitDependencies {
    desktopConfig?: Partial<DesktopConfigValues> | null
}

type ReactConfigKey = Extract<ConfigKey, `react.${string}`>

function requireString(value: unknown, fieldName: string) {
    if (typeof value !== 'string' || value.length === 0) throw new Error(`Missing config field: ${fieldName}`)

    return value
}

function requireNumber(value: unknown, fieldName: string) {
    if (typeof value !== 'number' || Number.isNaN(value)) throw new Error(`Missing config field: ${fieldName}`)

    return value
}

function requireBoolean(value: unknown, fieldName: string) {
    if (typeof value !== 'boolean') throw new Error(`Missing config field: ${fieldName}`)

    return value
}

function normalizeConfigPath(value: string, fieldName: string, allowEmpty = false) {
    const normalized = value.replace(/\\/gu, '/').replace(/\/+/gu, '/').replace(/^\/+|\/+$/gu, '')
    if (!allowEmpty && normalized.length === 0) throw new Error(`Missing config field: ${fieldName}`)
    if (/^[a-zA-Z]:/u.test(value) || value.startsWith('/') || value.startsWith('\\')) {
        throw new Error(`Config path ${fieldName} must be repository-relative`)
    }
    if (normalized.split('/').some((segment) => segment === '.' || segment === '..')) {
        throw new Error(`Config path ${fieldName} must stay inside the project folder`)
    }

    return normalized
}

const PROJECT_SUBFOLDER_KEYS = [
    'project.workingFolder',
    'project.actionsFolder',
    'project.releasesFolder',
    'project.archivedFolder',
] as const

function validateProjectFolderPaths(values: ConfigValues) {
    const configuredPaths: Array<{ key: ConfigKey; path: string }> = []

    for (const key of PROJECT_SUBFOLDER_KEYS) {
        const path = values[key].toLowerCase()
        const conflict = configuredPaths.find(({ path: configuredPath }) => (
            path === configuredPath
            || path.startsWith(`${configuredPath}/`)
            || configuredPath.startsWith(`${path}/`)
        ))
        if (conflict) throw new Error(`Config folders ${conflict.key} and ${key} must not overlap`)

        configuredPaths.push({ key, path })
    }
}

function validateCardTypes(value: unknown): CardTypeConfig[] {
    if (!Array.isArray(value) || value.length === 0) throw new Error('Missing config field: project.cardTypes')

    return value.map((cardType, index) => {
        const item = cardType as Partial<CardTypeConfig>

        return {
            color: requireString(item.color, `project.cardTypes[${index}].color`),
            idPrefix: requireString(item.idPrefix, `project.cardTypes[${index}].idPrefix`),
            label: requireString(item.label, `project.cardTypes[${index}].label`),
            type: requireString(item.type, `project.cardTypes[${index}].type`) as CardTypeConfig['type'],
        }
    })
}

function validateStates(value: unknown): StateConfig[] {
    if (!Array.isArray(value) || value.length === 0) throw new Error('Missing config field: project.states')

    const states = value.map((stateConfig, index) => {
        const item = stateConfig as Partial<StateConfig>
        const color = item.color === undefined || item.color === null || item.color === ''
            ? defaultColumnAccent(index)
            : requireString(item.color, `project.states[${index}].color`)

        return {
            alwaysVisible: requireBoolean(item.alwaysVisible, `project.states[${index}].alwaysVisible`),
            color,
            state: requireString(item.state, `project.states[${index}].state`),
        }
    })
    const uniqueStates = new Set(states.map(({ state }) => state))
    if (uniqueStates.size !== states.length) throw new Error('Config field project.states contains duplicate states')

    return states
}

function validateDesktopAgentProfiles(value: unknown): AgentProfile[] {
    return validateAgentProfiles(value)
}

function validateOption(value: string, entry: ConfigEntry) {
    if (!entry.options) return value
    if (!entry.options.some((option) => option.value === value)) throw new Error(`Invalid config value for ${entry.key}: ${value}`)

    return value
}

function validateValue<K extends ConfigKey>(key: K, value: unknown): ConfigValueTypes[K] {
    const entry = requireConfigEntry(key)

    if (entry.type === 'boolean') return requireBoolean(value, entry.key) as ConfigValueTypes[K]
    if (entry.type === 'number') {
        const numberValue = requireNumber(value, entry.key)
        if (entry.integer && !Number.isInteger(numberValue)) throw new Error(`Config value ${entry.key} must be an integer`)
        if (entry.min !== undefined && numberValue < entry.min) throw new Error(`Config value ${entry.key} is below ${entry.min}`)
        if (entry.max !== undefined && numberValue > entry.max) throw new Error(`Config value ${entry.key} is above ${entry.max}`)

        return numberValue as ConfigValueTypes[K]
    }
    if (entry.type === 'json' && key === 'project.cardTypes') return validateCardTypes(value) as ConfigValueTypes[K]
    if (entry.type === 'json' && key === 'project.states') return validateStates(value) as ConfigValueTypes[K]
    if (entry.type === 'json' && key === 'desktop.agentProfiles') return validateDesktopAgentProfiles(value) as ConfigValueTypes[K]
    if (key === 'project.projectFolder') {
        if (typeof value !== 'string') throw new Error(`Missing config field: ${entry.key}`)

        return normalizeConfigPath(value, entry.key, true) as ConfigValueTypes[K]
    }
    if (
        key === 'project.workingFolder'
        || key === 'project.actionsFolder'
        || key === 'project.releasesFolder'
        || key === 'project.archivedFolder'
    ) {
        return normalizeConfigPath(requireString(value, entry.key), entry.key) as ConfigValueTypes[K]
    }
    if (key === 'desktop.model') {
        if (typeof value !== 'string') throw new Error(`Missing config field: ${entry.key}`)

        return value as ConfigValueTypes[K]
    }
    if (key === 'desktop.permissionMode') return validatePermissionMode(value, entry.key) as ConfigValueTypes[K]
    if (key === 'desktop.thinkingLevel') return validateThinkingLevel(value, entry.key) as ConfigValueTypes[K]
    if (key === 'desktop.editorCommand') {
        const editorCommand = requireString(value, entry.key)
        if (!editorCommand.includes('{{file}}')) throw new Error('Config field desktop.editorCommand requires {{file}} placeholder')

        return editorCommand as ConfigValueTypes[K]
    }
    if (key === 'desktop.mergeConflictResolverCommand') {
        if (typeof value !== 'string') throw new Error(`Missing config field: ${entry.key}`)
        if (value.length > 0 && !value.includes('{{file}}')) {
            throw new Error('Config field desktop.mergeConflictResolverCommand requires {{file}} placeholder when configured')
        }

        return value as ConfigValueTypes[K]
    }

    return validateOption(requireString(value, entry.key), entry) as ConfigValueTypes[K]
}

function mergeValue<K extends ConfigKey>(values: ConfigValues, key: K, value: unknown): ConfigValues {
    return { ...values, [key]: validateValue(key, value) }
}

function readProjectConfig(values: ConfigValues): ProjectConfig {
    return {
        actionsFolder: values['project.actionsFolder'],
        archivedFolder: values['project.archivedFolder'],
        backgroundShade: values['project.backgroundShade'],
        cardBodyTemplate: values['project.cardBodyTemplate'],
        cardSeparator: values['project.cardSeparator'],
        cardTypes: values['project.cardTypes'],
        diffCommand: values['project.diffCommand'],
        projectFolder: values['project.projectFolder'],
        pushMode: values['project.pushMode'],
        releasesFolder: values['project.releasesFolder'],
        states: values['project.states'],
        workingFolder: values['project.workingFolder'],
    }
}

function readDesktopConfig(values: ConfigValues): DesktopConfigValues {
    return {
        agent: values['desktop.agent'],
        agentProfiles: values['desktop.agentProfiles'],
        codexSearchEnabled: values['desktop.codexSearchEnabled'],
        editorCommand: values['desktop.editorCommand'],
        mergeConflictResolverCommand: values['desktop.mergeConflictResolverCommand'],
        model: values['desktop.model'],
        permissionMode: values['desktop.permissionMode'],
        remoteControlPort: values['desktop.remoteControlPort'],
        thinkingLevel: values['desktop.thinkingLevel'],
    }
}

function isConfigValueEqual(first: ConfigValue, second: ConfigValue) {
    if (Object.is(first, second)) return true

    return JSON.stringify(first) === JSON.stringify(second)
}

function replaceDesktopValues(values: ConfigValues, desktopConfig: Partial<DesktopConfigValues> | null) {
    const defaults = createDefaultValues()
    let nextValues = values
    for (const key of DESKTOP_KEYS) nextValues = { ...nextValues, [key]: defaults[key] }

    if (!desktopConfig) return nextValues
    if (desktopConfig.agent !== undefined) nextValues = mergeValue(nextValues, 'desktop.agent', desktopConfig.agent)
    if (desktopConfig.agentProfiles !== undefined) nextValues = mergeValue(nextValues, 'desktop.agentProfiles', desktopConfig.agentProfiles)
    if (desktopConfig.codexSearchEnabled !== undefined) {
        nextValues = mergeValue(nextValues, 'desktop.codexSearchEnabled', desktopConfig.codexSearchEnabled)
    }
    if (desktopConfig.editorCommand !== undefined) nextValues = mergeValue(nextValues, 'desktop.editorCommand', desktopConfig.editorCommand)
    if (desktopConfig.mergeConflictResolverCommand !== undefined) {
        nextValues = mergeValue(nextValues, 'desktop.mergeConflictResolverCommand', desktopConfig.mergeConflictResolverCommand)
    }
    if (desktopConfig.model !== undefined) nextValues = mergeValue(nextValues, 'desktop.model', desktopConfig.model)
    if (desktopConfig.permissionMode !== undefined) {
        nextValues = mergeValue(nextValues, 'desktop.permissionMode', desktopConfig.permissionMode)
    }
    if (desktopConfig.thinkingLevel !== undefined) {
        nextValues = mergeValue(nextValues, 'desktop.thinkingLevel', desktopConfig.thinkingLevel)
    }

    return nextValues
}

export class ConfigService extends EventTarget {
    private desktopAvailable: boolean
    private draftValues: ConfigValues | null
    private initialized: boolean
    private projectLoaded: boolean
    private values: ConfigValues

    constructor() {
        super()
        this.desktopAvailable = false
        this.draftValues = null
        this.initialized = false
        this.projectLoaded = false
        this.values = createDefaultValues()
        register('configService', this)
    }

    init(dependencies: ConfigServiceInitDependencies = {}) {
        let nextValues = createDefaultValues()
        const { desktopConfig } = dependencies
        this.desktopAvailable = !!desktopConfig
        this.projectLoaded = false
        this.draftValues = null

        nextValues = mergeStoredReactValues(nextValues, mergeValue)

        nextValues = replaceDesktopValues(nextValues, desktopConfig ?? null)

        this.initialized = true
        this.values = nextValues
        this.dispatchChanged()
    }

    getEntries(): ConfigEntry[] {
        this.requireInitialized()

        return CONFIG_ENTRIES.filter((entry) => {
            if (entry.source === 'desktop') return true
            if (entry.source === 'project') return this.projectLoaded

            return true
        })
    }

    get<K extends ConfigKey>(key: K): ConfigValueTypes[K] {
        this.requireInitialized()

        return this.values[key]
    }

    set<K extends ConfigKey>(key: K, value: ConfigValueTypes[K]) {
        this.requireInitialized()
        this.values = mergeValue(this.values, key, value)
        this.dispatchChanged()
    }

    setReactPreference<K extends ReactConfigKey>(key: K, value: ConfigValueTypes[K]) {
        this.requireInitialized()
        this.values = mergeValue(this.values, key, value)
        writeStoredReactValues(this.values)
        this.dispatchChanged()
    }

    clear() {
        this.values = createDefaultValues()
        this.draftValues = null
        this.desktopAvailable = false
        this.projectLoaded = false
        this.initialized = false
        this.dispatchChanged()
    }

    replaceDesktopConfig(desktopConfig: Partial<DesktopConfigValues>) {
        this.requireInitialized()
        this.values = replaceDesktopValues(this.values, desktopConfig)
        if (this.draftValues) this.draftValues = replaceDesktopValues(this.draftValues, desktopConfig)
        this.desktopAvailable = true
        this.dispatchChanged()
    }

    clearDesktopConfig() {
        this.requireInitialized()
        this.values = replaceDesktopValues(this.values, null)
        if (this.draftValues) this.draftValues = replaceDesktopValues(this.draftValues, null)
        this.desktopAvailable = false
        this.dispatchChanged()
    }

    loadProjectConfig(projectConfig: Partial<ProjectConfig> | null) {
        this.requireInitialized()
        let nextValues = this.values
        for (const key of PROJECT_KEYS) {
            nextValues = { ...nextValues, [key]: requireConfigEntry(key).defaultValue }
        }

        if (projectConfig && projectConfig.cardSeparator === undefined) {
            nextValues = mergeValue(nextValues, 'project.cardSeparator', LEGACY_CARD_SEPARATOR)
        }

        if (projectConfig?.workingFolder !== undefined) nextValues = mergeValue(nextValues, 'project.workingFolder', projectConfig.workingFolder)
        if (projectConfig?.actionsFolder !== undefined) nextValues = mergeValue(nextValues, 'project.actionsFolder', projectConfig.actionsFolder)
        if (projectConfig?.archivedFolder !== undefined) {
            nextValues = mergeValue(nextValues, 'project.archivedFolder', projectConfig.archivedFolder)
        }
        if (projectConfig?.backgroundShade !== undefined) {
            nextValues = mergeValue(nextValues, 'project.backgroundShade', projectConfig.backgroundShade)
        }
        if (projectConfig?.projectFolder !== undefined) nextValues = mergeValue(nextValues, 'project.projectFolder', projectConfig.projectFolder)
        if (projectConfig?.diffCommand !== undefined) nextValues = mergeValue(nextValues, 'project.diffCommand', projectConfig.diffCommand)
        if (projectConfig?.pushMode !== undefined) nextValues = mergeValue(nextValues, 'project.pushMode', projectConfig.pushMode)
        if (projectConfig?.releasesFolder !== undefined) {
            nextValues = mergeValue(nextValues, 'project.releasesFolder', projectConfig.releasesFolder)
        }
        if (projectConfig?.cardBodyTemplate !== undefined) {
            nextValues = mergeValue(nextValues, 'project.cardBodyTemplate', projectConfig.cardBodyTemplate)
        }
        if (projectConfig?.cardSeparator !== undefined) {
            nextValues = mergeValue(nextValues, 'project.cardSeparator', projectConfig.cardSeparator)
        }
        if (projectConfig?.cardTypes !== undefined) nextValues = mergeValue(nextValues, 'project.cardTypes', projectConfig.cardTypes)
        if (projectConfig?.states !== undefined) nextValues = mergeValue(nextValues, 'project.states', projectConfig.states)

        validateProjectFolderPaths(nextValues)
        this.values = nextValues
        this.projectLoaded = true
        this.dispatchChanged()
    }

    getProjectConfig(): ProjectConfig {
        this.requireInitialized()

        return readProjectConfig(this.values)
    }

    getDesktopValues(): DesktopConfigValues {
        this.requireInitialized()

        return readDesktopConfig(this.values)
    }

    getDraftDesktopValues(): DesktopConfigValues {
        return readDesktopConfig(this.requireDraft())
    }

    loadDraft() {
        this.requireInitialized()
        this.draftValues = { ...this.values }
        this.dispatchChanged()

        return this.requireDraft()
    }

    getDraft(): ConfigValues | null {
        return this.draftValues
    }

    setDraftValue(key: ConfigKey, value: unknown) {
        const draft = this.requireDraft()
        this.draftValues = mergeValue(draft, key, value)
        this.dispatchChanged()
    }

    hasDraftChangesForSource(source: ConfigSource) {
        const draft = this.requireDraft()

        return CONFIG_ENTRIES.some((entry) => entry.source === source && !isConfigValueEqual(draft[entry.key], this.values[entry.key]))
    }

    saveDraft() {
        const draft = this.requireDraft()
        for (const key of PROJECT_KEYS) validateValue(key, draft[key])
        validateProjectFolderPaths(draft)
        this.values = draft
        this.draftValues = null
        writeStoredReactValues(this.values)
        this.dispatchChanged()

        return this.values
    }

    discardDraft() {
        this.draftValues = null
        this.dispatchChanged()
    }

    hasProjectConfig() {
        return this.projectLoaded
    }

    hasDesktopConfig() {
        return this.desktopAvailable
    }

    isInitialized() {
        return this.initialized
    }

    private requireDraft() {
        if (!this.draftValues) throw new Error('Config draft is not loaded')

        return this.draftValues
    }

    private requireInitialized() {
        if (!this.initialized) throw new Error('Config service is not initialized')
    }

    private dispatchChanged() {
        this.dispatchEvent(new CustomEvent('changed'))
    }
}

export const configService = new ConfigService()

import {
    Box,
    FormControl,
    FormControlLabel,
    FormHelperText,
    FormLabel,
    InputLabel,
    MenuItem,
    Select,
    Slider,
    Switch,
    TextField,
} from '@mui/material'
import type { SelectChangeEvent } from '@mui/material'
import { Fragment, useEffect, useState } from 'react'
import type { ChangeEvent } from 'react'
import type { ConfigEntry, ConfigValue } from '../../services/config/config_service'
import { dialogService } from '../../services/dialog_service'
import {
    defaultModelForProfile,
    findAgentProfile,
    mergeAgentProfiles,
    supportsPermissionMode,
    type AgentProfile,
} from '../../data/agent_profiles'
import { AgentProfilesEditor } from './agent_profiles_editor'

const CONFIG_PLACEHOLDER_PARTS_PATTERN = /(\{\{[^{}]+\}\})/u
const CONFIG_PLACEHOLDER_PATTERN = /^\{\{[^{}]+\}\}$/u
const MULTILINE_CONFIG_FIELD_MIN_ROWS = 6
const OUTLINED_FIELD_BLOCK_SX = { border: 1, borderColor: 'divider', borderRadius: 1, p: 2 }
const MONOSPACE_INPUT_SLOT_PROPS = { htmlInput: { style: { fontFamily: 'monospace' } } }
const MONOSPACE_CONFIG_KEYS = new Set<ConfigEntry['key']>([
    'project.cardBodyTemplate',
    'project.cardTypes',
    'project.diffCommand',
    'project.states',
])

interface ConfigValueEditorProps {
    disabled?: boolean
    entry: ConfigEntry
    onChange: (key: ConfigEntry['key'], value: unknown) => void
    onValidityChange?: (key: ConfigEntry['key'], valid: boolean) => void
    value: ConfigValue
    values?: Partial<Record<ConfigEntry['key'], ConfigValue>>
}

function renderDescription(description: string) {
    return description.split(CONFIG_PLACEHOLDER_PARTS_PATTERN).map((descriptionPart, index) => {
        if (!CONFIG_PLACEHOLDER_PATTERN.test(descriptionPart)) {
            return <Fragment key={`${descriptionPart}-${index}`}>{descriptionPart}</Fragment>
        }

        return (
            <Box component="code" key={`${descriptionPart}-${index}`} sx={{ bgcolor: 'action.hover', borderRadius: 0.5, px: 0.5 }}>
                {descriptionPart}
            </Box>
        )
    })
}

export function ConfigValueEditor(props: ConfigValueEditorProps) {
    const { disabled = false, entry, onChange, onValidityChange, value, values } = props
    const [jsonText, setJsonText] = useState(() => (entry.type === 'json' ? JSON.stringify(value, null, 2) : ''))
    const [numberText, setNumberText] = useState(() => (entry.type === 'number' ? String(value) : ''))
    const [numberValid, setNumberValid] = useState(true)
    const agentProfiles = mergeAgentProfiles((values?.['desktop.agentProfiles'] ?? []) as AgentProfile[])
    const selectedAgentProfile = findAgentProfile(agentProfiles, (values?.['desktop.agent'] ?? '') as string)
    const selectedAgentModels = selectedAgentProfile?.models ?? []
    const stringValue = value as string
    const selectOptions = entry.key === 'desktop.agent'
        ? agentProfiles.map((profile) => ({ label: profile.name, value: profile.name }))
        : entry.key === 'desktop.model' && selectedAgentModels.length > 0
            ? selectedAgentModels.map((model) => ({ label: model, value: model }))
            : entry.type === 'select'
                ? entry.options ?? []
                : null
    const selectValue = entry.key === 'desktop.model' && selectedAgentModels.length > 0 && stringValue.length === 0
        ? defaultModelForProfile(selectedAgentProfile as AgentProfile)
        : stringValue
    const helperTextId = `${entry.key}-helper-text`
    const selectLabelId = `${entry.key}-label`
    const description = renderDescription(entry.description)
    const isMultilineString = entry.key === 'project.cardBodyTemplate'
    const usesMonospace = MONOSPACE_CONFIG_KEYS.has(entry.key)
    const sliderConfigurationError = entry.type === 'number'
        && entry.input === 'slider'
        && (entry.min === undefined || entry.max === undefined)
        ? `Slider config entry ${entry.key} requires min and max`
        : null

    useEffect(() => {
        if (sliderConfigurationError) dialogService.error(sliderConfigurationError)
    }, [sliderConfigurationError])

    const handleBooleanChange = (event: ChangeEvent<HTMLInputElement>) => {
        onChange(entry.key, event.target.checked)
    }

    const handleNumberChange = (event: ChangeEvent<HTMLInputElement>) => {
        const nextText = event.target.value
        const nextValue = Number(nextText)
        const valid = nextText.length > 0
            && Number.isFinite(nextValue)
            && (!entry.integer || Number.isInteger(nextValue))
            && (entry.min === undefined || nextValue >= entry.min)
            && (entry.max === undefined || nextValue <= entry.max)
        setNumberText(nextText)
        setNumberValid(valid)
        onValidityChange?.(entry.key, valid)
        if (valid) onChange(entry.key, nextValue)
    }

    const handleSliderChange = (_event: Event, nextValue: number | number[]) => {
        onChange(entry.key, nextValue)
    }

    const handleStringChange = (event: ChangeEvent<HTMLInputElement>) => {
        onChange(entry.key, event.target.value)
    }

    const handleSelectChange = (event: SelectChangeEvent) => {
        if (entry.key === 'desktop.agent') {
            const profile = findAgentProfile(agentProfiles, event.target.value)
            onChange('desktop.model', profile ? defaultModelForProfile(profile) : '')
        }
        onChange(entry.key, event.target.value)
    }

    const handleJsonChange = (event: ChangeEvent<HTMLInputElement>) => {
        setJsonText(event.target.value)
    }

    const handleJsonBlur = () => {
        onChange(entry.key, JSON.parse(jsonText))
    }

    const handleAgentProfilesChange = (nextValue: AgentProfile[]) => {
        onChange(entry.key, nextValue)
    }

    const handleAgentProfilesValidityChange = (valid: boolean) => {
        onValidityChange?.(entry.key, valid)
    }

    if (sliderConfigurationError) return null

    if (entry.key === 'desktop.permissionMode' && (!selectedAgentProfile || !supportsPermissionMode(selectedAgentProfile))) {
        return <TextField disabled fullWidth helperText={`${selectedAgentProfile?.name ?? 'Selected agent'} does not support permission modes.`} label={entry.label} value="Not supported" />
    }

    if (entry.type === 'boolean') {
        return (
            <FormControl disabled={disabled} fullWidth sx={OUTLINED_FIELD_BLOCK_SX}>
                <FormControlLabel
                    control={(
                        <Switch
                            checked={value as boolean}
                            disabled={disabled}
                            onChange={handleBooleanChange}
                            slotProps={{ input: { 'aria-describedby': helperTextId } }}
                        />
                    )}
                    label={entry.label}
                    sx={{ m: 0 }}
                />
                <FormHelperText id={helperTextId} sx={{ m: 0, mt: 1 }}>{description}</FormHelperText>
            </FormControl>
        )
    }

    if (selectOptions) {
        return (
            <FormControl disabled={disabled} fullWidth variant="outlined">
                <InputLabel id={selectLabelId}>{entry.label}</InputLabel>
                <Select
                    aria-describedby={helperTextId}
                    label={entry.label}
                    labelId={selectLabelId}
                    onChange={handleSelectChange}
                    value={selectValue}
                >
                    {selectOptions.map((option) => (
                        <MenuItem key={option.value} value={option.value}>{option.label}</MenuItem>
                    ))}
                </Select>
                <FormHelperText id={helperTextId}>{description}</FormHelperText>
            </FormControl>
        )
    }

    if (entry.type === 'number' && entry.input === 'slider') {
        return (
            <FormControl disabled={disabled} fullWidth sx={OUTLINED_FIELD_BLOCK_SX}>
                <FormLabel htmlFor={entry.key}>{entry.label}</FormLabel>
                <Slider
                    aria-label={entry.label}
                    aria-describedby={helperTextId}
                    disabled={disabled}
                    id={entry.key}
                    max={entry.max}
                    min={entry.min}
                    onChange={handleSliderChange}
                    step={entry.step}
                    value={value as number}
                    valueLabelDisplay="auto"
                />
                <FormHelperText id={helperTextId} sx={{ m: 0 }}>{description}</FormHelperText>
            </FormControl>
        )
    }

    if (entry.type === 'number') {
        return (
            <TextField
                disabled={disabled}
                error={!numberValid}
                fullWidth
                helperText={description}
                label={entry.label}
                onChange={handleNumberChange}
                slotProps={{ htmlInput: { max: entry.max, min: entry.min, step: entry.step } }}
                type="number"
                value={numberText}
                variant="outlined"
            />
        )
    }

    if (entry.key === 'desktop.agentProfiles') {
        return (
            <FormControl disabled={disabled} fullWidth sx={OUTLINED_FIELD_BLOCK_SX}>
                <FormLabel>{entry.label}</FormLabel>
                <Box sx={{ mt: 2 }}>
                    <AgentProfilesEditor
                        disabled={disabled}
                        onChange={handleAgentProfilesChange}
                        onValidityChange={handleAgentProfilesValidityChange}
                        value={value as AgentProfile[]}
                    />
                </Box>
                <FormHelperText sx={{ m: 0, mt: 1 }}>{description}</FormHelperText>
            </FormControl>
        )
    }

    if (entry.type === 'json') {
        return (
            <TextField
                disabled={disabled}
                fullWidth
                helperText={description}
                label={entry.label}
                minRows={MULTILINE_CONFIG_FIELD_MIN_ROWS}
                multiline
                onBlur={handleJsonBlur}
                onChange={handleJsonChange}
                slotProps={MONOSPACE_INPUT_SLOT_PROPS}
                value={jsonText}
                variant="outlined"
            />
        )
    }

    return (
        <TextField
            disabled={disabled}
            fullWidth
            helperText={description}
            label={entry.label}
            minRows={isMultilineString ? MULTILINE_CONFIG_FIELD_MIN_ROWS : undefined}
            multiline={isMultilineString}
            onChange={handleStringChange}
            slotProps={usesMonospace ? MONOSPACE_INPUT_SLOT_PROPS : undefined}
            value={stringValue}
            variant="outlined"
        />
    )
}

